function npcCastSkill(actor, skill, index, target, opts = {}) {
  if (!actor || !skill || !target || !target.alive || !Number.isInteger(index)
    || !Array.isArray(actor.skillCooldowns) || index < 0 || index >= actor.skillCooldowns.length) return false;
  if (actor.mana < skill.cost || (!opts?.freeCleanse && actor.skillCooldowns[index] > 0)) return false;
  actor.mana -= skill.cost;
  // Remover parálisis es su propio hechizo en la práctica: no queda amarrado al cooldown completo de la cura.
  actor.skillCooldowns[index] = opts?.freeCleanse
    ? Math.max(actor.skillCooldowns[index] ?? 0, 1.2)
    : skill.type === 'heal' ? 5 : 4.2 + index * .8;

