    const arm = tilePx * .42, gap = tilePx * .17;
    ctx.beginPath();
    ctx.moveTo(x - arm, y); ctx.lineTo(x - gap, y); ctx.moveTo(x + gap, y); ctx.lineTo(x + arm, y);
    ctx.moveTo(x, y - arm); ctx.lineTo(x - ...); ... stroke();
    ctx.restore();
  }
